// The text of src/templates.ts for the files under templates/.chernabog/. A
// test renders it again to check the generated file is current.

import { fileURLToPath } from 'node:url';

import { printJson } from '@chernabog/sdk';
import * as Arr from 'effect/Array';
import * as Effect from 'effect/Effect';
import * as FileSystem from 'effect/FileSystem';
import * as Order from 'effect/Order';

export const templatesRoot = fileURLToPath(new URL('../templates/.chernabog/', import.meta.url));

export const renderTemplates = (root: string) =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const entries = yield* fs.readDirectory(root, { recursive: true });
    const files: Array<string> = [];

    for (const entry of Arr.sort(entries, Order.String)) {
      if ((yield* fs.stat(`${root}${entry}`)).type === 'File') files.push(entry);
    }

    const contents = yield* Effect.forEach(files, (file) => fs.readFileString(`${root}${file}`));

    const lines = [
      '// Generated by scripts/gen-templates.ts from templates/.chernabog/. Do not edit.',
      '',
      'export const TEMPLATES = {',
      ...files.map((file, index) => `  ${printJson(file)}: ${printJson(contents[index] ?? '')},`),
      '} as const;',
      '',
    ];

    return { count: files.length, text: lines.join('\n') };
  });
